// ME: LENS cabin cutaway: vehicle body shading with a clip plane and interior light.
// Built from the game's own vehicle_multiuv shader (skin/mask on the first UV set,
// rust/damage/blood on the second), minus paint recolouring so a camper's skin
// keeps its own colours. Everything above the cut is discarded (see meLensCutHeight).

varying vec3 vertColour;
varying vec3 vertNormal;
varying vec2 texCoords;
varying vec2 texCoords1;
varying vec4 positionEye;
varying vec3 meLensMeshPos;
varying vec3 meLensMeshNormal;

uniform vec4 MELensBodyPlane;   // the cut in the body's mesh space: fragments with a*x+b*y+c*z+d > 0 are cut away
uniform vec4 MELensNearCut;     // xy: towards the camera (body space), z: plane d for the walls facing it, w: 1 = on
uniform vec4 MELensKeepPlane;    // parts of other mods' models removed on every camper: a*x+b*y+c*z+d > 0 is not drawn
uniform vec4 MELensCutFront;     // x: body y (towards the front) beyond which nothing is cut (a bus's hood), y: ... up to this body z (higher up is cut as usual), w: 1 = on
uniform mat4 MELensToBody;      // this mesh's space -> the camper body's mesh space
uniform vec4 MELensBodyUp;      // xyz: up in body space; w: 0 no interior light, 1 all faces, 2 faces looking into the camper
uniform vec4 MELensShape;       // body footprint in body space: min a, min b, max a, max b (a, b = x, y)
uniform vec4 MELensFill;        // x: share of the ambient light, y: constant light, z: top-down bias
uniform vec4 MELensLamp0;       // xyz: lamp position in body space, w: reach (0 = off)
uniform vec4 MELensLamp1;
uniform vec3 MELensLampColour;
uniform vec4 MELensMarker;       // xyz: centre of the floor marker (body space), w: strength (0 = hidden)
uniform vec4 MELensMarkerSize;   // x, y: half size (body space), z: height tolerance around the floor
uniform vec3 MELensMarkerColour;
uniform vec4 MELensDoor;         // xyz: the colour the inside of a door leaf is painted, w: 1 = this model is a door leaf
uniform vec4 MELensRoom;         // the room's floor outline: x: corners (0 = off), y: the floor's height along the body's up; z, w: heights above the floor between which body details inside it are not drawn
uniform vec4 MELensRoomCut;      // x: only faces looking up at least this much (along the body's up, -1..1) are removed: the hull's own bevel looks down and stays; y: 1 = paint what would go magenta (debugging); z: windows (boxes in MELensWin); w: how dark KI5's skin must be, inside a window's box, not to be drawn
uniform vec3 MELensWin[24];      // the windows' boxes in body space: min, max, min, max, ...
uniform vec4 MELensJambCount;    // x: how many door frame boxes: the dark skin inside them that looks along the camper is painted like the room
uniform vec3 MELensJamb[8];      // the door frames' boxes in body space: min, max, min, max, ...
uniform vec2 MELensRing[80];     // the outline's corners in body space (x, y)
uniform vec3 MELensClipMin0;     // the wheel-well boxes (body space): their wheels stay
uniform vec3 MELensClipMax0;
uniform vec3 MELensClipMin1;
uniform vec3 MELensClipMax1;

uniform sampler2D Texture0;
uniform vec4 TexturePainColor;
uniform sampler2D TextureRust;
uniform float TextureRustA;
uniform sampler2D TextureMask;
uniform sampler2D TextureLights;
uniform sampler2D TextureDamage1Overlay;
uniform sampler2D TextureDamage1Shell;
uniform sampler2D TextureDamage2Overlay;
uniform sampler2D TextureDamage2Shell;
uniform sampler2D TextureReflectionA;
uniform sampler2D TextureReflectionB;
uniform vec3 ReflectionParam;

uniform mat4 TextureUninstall1;
uniform mat4 TextureUninstall2;
uniform mat4 TextureLightsEnables1;
uniform mat4 TextureLightsEnables2;
uniform mat4 TextureDamage1Enables1;
uniform mat4 TextureDamage1Enables2;
uniform mat4 TextureDamage2Enables1;
uniform mat4 TextureDamage2Enables2;
uniform mat4 MatBlood1Enables1;
uniform mat4 MatBlood1Enables2;
uniform mat4 MatBlood2Enables1;
uniform mat4 MatBlood2Enables2;

uniform vec3 TintColour;

uniform vec3 AmbientColour;
uniform vec3 Light0Direction;
uniform vec3 Light0Colour;
uniform vec3 Light1Direction;
uniform vec3 Light1Colour;
uniform vec3 Light2Direction;
uniform vec3 Light2Colour;
uniform vec3 Light3Direction;
uniform vec3 Light3Colour;
uniform vec3 Light4Direction;
uniform vec3 Light4Colour;

#include "util/math"
#include "util/SphereMap"
#include "util/dommat4"

#include "vehicle_common.frag"

float meLensLamp(vec4 lamp, vec3 p, vec3 n)
{
	if (lamp.w <= 0.0)
		return 0.0;
	vec3 d = lamp.xyz - p;
	float dist = length(d);
	float reach = clamp(1.0 - dist / lamp.w, 0.0, 1.0);
	return reach * reach * (0.3 + 0.7 * max(dot(n, d / max(dist, 0.0001)), 0.0));
}

// A green rectangle on the floor, like the game's marker at a usable car door.
float meLensMarker(vec3 p, vec3 n, vec3 up)
{
	if (MELensMarker.w <= 0.0)
		return 0.0;
	vec3 d = p - MELensMarker.xyz;
	if (abs(dot(d, up)) > MELensMarkerSize.z || dot(n, up) < 0.7)
		return 0.0;
	vec2 q = abs(d.xy) / MELensMarkerSize.xy;
	float edge = max(q.x, q.y);
	float outline = smoothstep(0.80, 0.88, edge) * (1.0 - smoothstep(0.97, 1.0, edge));
	float inside = edge < 1.0 ? 0.2 : 0.0;
	return MELensMarker.w * max(outline, inside);
}

// How much a face looks into the room (towards the body's long axis): 1 facing in, -1 out.
float meLensInward(vec3 p, vec3 n)
{
	vec2 lo = MELensShape.xy;
	vec2 hi = MELensShape.zw;
	vec2 centre = 0.5 * (lo + hi);
	vec2 halfSize = 0.5 * (hi - lo);
	float radius = min(halfSize.x, halfSize.y);
	vec2 axisHalf = halfSize - vec2(radius);
	vec2 offset = p.xy - centre;
	vec2 toAxis = centre + vec2(clamp(offset.x, -axisHalf.x, axisHalf.x), clamp(offset.y, -axisHalf.y, axisHalf.y)) - p.xy;
	float dist = length(toAxis);
	return dist > 0.0001 ? dot(n.xy, toAxis / dist) : 1.0;
}

// Light inside the camper: daylight falling in plus the camper's lamps. Only surfaces
// inside the camper get it, so the outside keeps the game's own vehicle lighting.
vec3 meLensInteriorLight()
{
	if (MELensBodyUp.w < 0.5)
		return vec3(0.0);
	vec3 p = (MELensToBody * vec4(meLensMeshPos, 1.0)).xyz;
	vec3 n = normalize((MELensToBody * vec4(meLensMeshNormal, 0.0)).xyz);
	vec3 up = normalize(MELensBodyUp.xyz);
	float weight = 1.0;
	if (MELensBodyUp.w > 1.5)
	{
		// Shell and doors: faces that look towards the camper's long axis, or up from its floor.
		vec2 lo = MELensShape.xy;
		vec2 hi = MELensShape.zw;
		vec2 centre = 0.5 * (lo + hi);
		vec2 halfSize = 0.5 * (hi - lo);
		float radius = min(halfSize.x, halfSize.y);
		vec2 axisHalf = halfSize - vec2(radius);
		vec2 h = p.xy;
		// util/math redeclares clamp, which hides the built-in vector overloads.
		vec2 offset = h - centre;
		vec2 toAxis = centre + vec2(clamp(offset.x, -axisHalf.x, axisHalf.x), clamp(offset.y, -axisHalf.y, axisHalf.y)) - h;
		float dist = length(toAxis);
		float inward = dist > 0.0001 ? smoothstep(-0.05, 0.3, dot(n.xy, toAxis / dist)) : 1.0;
		float floorUp = smoothstep(0.5, 0.8, dot(n, up)) * step(dist, radius * 0.92);
		weight = max(inward, floorUp);
	}
	float hemi = mix(1.0, 0.55 + 0.45 * dot(n, up), MELensFill.z);
	vec3 light = (AmbientColour * MELensFill.x + vec3(MELensFill.y)) * hemi;
	// A lit camper is lit evenly and brightly, like a room with its lights on, with a
	// little extra near each lamp.
	float lampsOn = step(0.0001, MELensLamp0.w + MELensLamp1.w);
	float pools = min(meLensLamp(MELensLamp0, p, n) + meLensLamp(MELensLamp1, p, n), 1.0);
	light += MELensLampColour * (lampsOn * 0.95 + 0.25 * pools);
	return light * weight;
}

// How far a fragment is above the cut (> 0: cut away). The roof and upper walls are cut
// away; walls facing the camera are cut lower, like the game's cutaway of building walls;
// furniture in the middle keeps the normal cut.
float meLensCutHeight(vec3 p)
{
	if (dot(MELensKeepPlane.xyz, p) + MELensKeepPlane.w > 0.0)
		return 1.0;
	if (MELensCutFront.w > 0.5 && p.y > MELensCutFront.x && p.z > MELensCutFront.y)
		return -1.0;
	float d = MELensBodyPlane.w;
	if (MELensNearCut.w > 0.5)
	{
		vec2 lo = MELensShape.xy;
		vec2 hi = MELensShape.zw;
		vec2 centre = 0.5 * (lo + hi);
		vec2 halfSize = 0.5 * (hi - lo);
		float radius = min(halfSize.x, halfSize.y);
		vec2 axisHalf = halfSize - vec2(radius);
		vec2 offset = p.xy - centre;
		vec2 fromAxis = offset - vec2(clamp(offset.x, -axisHalf.x, axisHalf.x), clamp(offset.y, -axisHalf.y, axisHalf.y));
		float dist = length(fromAxis);
		if (dist > 0.0001)
		{
			float facing = dot(fromAxis / dist, MELensNearCut.xy);
			float nearWall = smoothstep(radius * 0.35, radius * 0.75, dist);
			d = mix(d, MELensNearCut.z, smoothstep(0.15, 0.55, facing) * nearWall);
		}
	}
	return dot(MELensBodyPlane.xyz, p) + d;
}

// How much a fragment is on the camera's side of the body (0 .. 1): the walls the camera sees from
// outside, which meLensCutHeight cuts down. What is on the other side is seen from inside.
float meLensNearSide(vec3 p)
{
	if (MELensNearCut.w < 0.5)
		return 0.0;
	vec2 lo = MELensShape.xy;
	vec2 hi = MELensShape.zw;
	vec2 centre = 0.5 * (lo + hi);
	vec2 halfSize = 0.5 * (hi - lo);
	float radius = min(halfSize.x, halfSize.y);
	vec2 axisHalf = halfSize - vec2(radius);
	vec2 offset = p.xy - centre;
	vec2 fromAxis = offset - vec2(clamp(offset.x, -axisHalf.x, axisHalf.x), clamp(offset.y, -axisHalf.y, axisHalf.y));
	float dist = length(fromAxis);
	if (dist < 0.0001)
		return 0.0;
	return smoothstep(0.15, 0.55, dot(fromAxis / dist, MELensNearCut.xy)) * smoothstep(radius * 0.35, radius * 0.75, dist);
}

bool meLensInBox(vec3 p, vec3 lo, vec3 hi)
{
	return p.x > lo.x && p.y > lo.y && p.z > lo.z && p.x < hi.x && p.y < hi.y && p.z < hi.z;
}

// KI5's body carries details inside its hull (the tips of a trailer tongue's arms at the front
// corners, a door frame's jamb) that stand inside ME: LENS' lining and show in front of its
// walls as black objects. Above the floor and below MELensRoom.w, inside the floor's outline
// (seen from above), the faces of KI5's body that look up or sideways are not drawn: the room
// is ME: LENS' own. The hull's own skin lies on the outline; where it tucks in under the floor
// it looks down, which is why only faces that do not look down go. The wheel wells' boxes are
// left alone, for their wheels.
bool meLensInsideRoom(vec3 p, vec3 n)
{
	if (MELensRoom.x < 2.5)
		return false;
	vec3 up = normalize(MELensBodyUp.xyz);
	float h = dot(up, p) - MELensRoom.y;
	if (h < MELensRoom.z || h > MELensRoom.w)
		return false;
	if (dot(up, n) < MELensRoomCut.x)
		return false;
	if (meLensInBox(p, MELensClipMin0, MELensClipMax0) || meLensInBox(p, MELensClipMin1, MELensClipMax1))
		return false;
	int count = int(MELensRoom.x + 0.5);
	bool inside = false;
	vec2 prev = MELensRing[count - 1];
	for (int i = 0; i < 80; i++)
	{
		if (i >= count)
			break;
		vec2 cur = MELensRing[i];
		if ((cur.y > p.y) != (prev.y > p.y) && p.x < (prev.x - cur.x) * (p.y - cur.y) / (prev.y - cur.y) + cur.x)
			inside = !inside;
		prev = cur;
	}
	return inside;
}

// KI5's windows are not drawn inside (the walls have no window openings), and what the hull keeps
// of one (the seal round its opening, a pillar between two panes) would stand on the cut walls'
// ramps as thin black posts: the body's skin inside a window's box is not drawn (skin darker
// than MELensRoomCut.w: all of it when that is above 1).
bool meLensInWindow(vec3 p)
{
	int count = int(MELensRoomCut.z + 0.5);
	for (int i = 0; i < 12; i++)
	{
		if (i >= count)
			break;
		if (meLensInBox(p, MELensWin[i * 2], MELensWin[i * 2 + 1]))
			return true;
	}
	return false;
}

// Whether a point is in a door frame's box (the jambs of the hull's door opening stand there).
bool meLensInJamb(vec3 p)
{
	int count = int(MELensJambCount.x + 0.5);
	for (int i = 0; i < 4; i++)
	{
		if (i >= count)
			break;
		if (meLensInBox(p, MELensJamb[i * 2], MELensJamb[i * 2 + 1]))
			return true;
	}
	return false;
}

vec3 meLensBodyPos = (MELensToBody * vec4(meLensMeshPos, 1.0)).xyz;
float meLensCut = meLensCutHeight(meLensBodyPos);
if (meLensCut > 0.0)
	discard;
vec3 meLensBodyNormal = normalize((MELensToBody * vec4(meLensMeshNormal, 0.0)).xyz);
bool meLensRemoved = meLensInsideRoom(meLensBodyPos, meLensBodyNormal);
if (meLensRemoved && MELensRoomCut.y < 0.5)
	discard;

vec3 normal = normalize(vertNormal);
vec4 tex = texture2D(Texture0, texCoords);
if (MELensRoomCut.z > 0.5 && dot(tex.xyz, vec3(0.299, 0.587, 0.114)) < MELensRoomCut.w && meLensInWindow(meLensBodyPos))
{
	if (MELensRoomCut.y < 0.5)
		discard;
	meLensRemoved = true;
}
vec3 col = tex.xyz;
float meLensPainted = 0.0;
// the jambs of a door opening (black rubber, faces along the camper) between the lining and the leaf: painted
// where they are seen from inside (the far side); on the camera's side they are seen from outside, against the
// hull, and keep KI5's black
if (MELensJambCount.x > 0.5 && abs(meLensBodyNormal.y) > 0.55 && dot(tex.xyz, vec3(0.299, 0.587, 0.114)) < 0.3 && meLensInJamb(meLensBodyPos))
{
	float far = 1.0 - meLensNearSide(meLensBodyPos);
	col = mix(col, MELensDoor.xyz, far);
	meLensPainted = far;
}
if (MELensDoor.w > 0.5)
{
	// the inside of a door leaf is bare black: painted like the room's walls. So is its thickness (its
	// edge) on the far side, which is seen from inside; on the camera's side the edge is seen from
	// outside, against the hull, and keeps KI5's paint.
	float inward = meLensInward(meLensBodyPos, meLensBodyNormal);
	float paint = max(smoothstep(0.0, 0.3, inward), smoothstep(-0.55, -0.25, inward) * (1.0 - meLensNearSide(meLensBodyPos)));
	col = mix(col, MELensDoor.xyz, paint);
	meLensPainted = paint;
}
float dotprod;

vec4 texColorMask = texture2D(TextureMask, texCoords);
vec4 texColorRust = texture2D(TextureRust, texCoords1);
vec4 texColorLights = texture2D(TextureLights, texCoords);
vec4 texColorDamage1Shell = texture2D(TextureDamage1Shell, texCoords1);
vec4 texColorDamage2Shell = texture2D(TextureDamage2Shell, texCoords1);

vec3 lighting = AmbientColour;
dotprod = max(dot(normal, normalize(Light0Direction)), 0.0);
quantise(dotprod, 3.0);
lighting += Light0Colour * dotprod;
dotprod = max(dot(normal, normalize(Light1Direction)), 0.0);
quantise(dotprod, 3.0);
lighting += Light1Colour * dotprod;
dotprod = max(dot(normal, normalize(Light2Direction)), 0.0);
quantise(dotprod, 3.0);
lighting += Light2Colour * dotprod;
dotprod = max(dot(normal, normalize(Light3Direction)), 0.0);
quantise(dotprod, 3.0);
lighting += Light3Colour * dotprod;
dotprod = max(dot(normal, normalize(Light4Direction)), 0.0);
quantise(dotprod, 3.0);
lighting += Light4Colour * dotprod;
lighting += meLensInteriorLight();

vec3 TintColourNew = desaturate(TintColour, 0.3);
lighting.x = clamp(lighting.x, 0.0, 1.0);
lighting.y = clamp(lighting.y, 0.0, 1.0);
lighting.z = clamp(lighting.z, 0.0, 1.0);

mat4 texen1 = mat4(0.0);
texen1[0][0] = (1.0-step(0.01,length(texColorMask.xyz-colZone1)));
texen1[0][1] = (1.0-step(0.01,length(texColorMask.xyz-colZone2)));
texen1[0][2] = (1.0-step(0.01,length(texColorMask.xyz-colZone3)));
texen1[0][3] = (1.0-step(0.01,length(texColorMask.xyz-colZone4)));
texen1[1][0] = (1.0-step(0.01,length(texColorMask.xyz-colZone5)));
texen1[1][1] = (1.0-step(0.01,length(texColorMask.xyz-colZone6)));
texen1[1][2] = (1.0-step(0.01,length(texColorMask.xyz-colZone7)));
texen1[1][3] = (1.0-step(0.01,length(texColorMask.xyz-colZone8)));
texen1[2][0] = (1.0-step(0.01,length(texColorMask.xyz-colZone9)));
texen1[2][1] = (1.0-step(0.01,length(texColorMask.xyz-colZone10)));
texen1[2][2] = (1.0-step(0.01,length(texColorMask.xyz-colZone11)));
texen1[2][3] = (1.0-step(0.01,length(texColorMask.xyz-colZone12)));
texen1[3][0] = (1.0-step(0.01,length(texColorMask.xyz-colZone13)));
texen1[3][1] = (1.0-step(0.01,length(texColorMask.xyz-colZone14)));
texen1[3][2] = (1.0-step(0.01,length(texColorMask.xyz-colZone15)));
texen1[3][3] = (1.0-step(0.01,length(texColorMask.xyz-colZone16)));

mat4 texen2 = mat4(0.0);
texen2[0][0] = (1.0-step(0.01,length(texColorMask.xyz-colZone17)));
texen2[0][1] = (1.0-step(0.01,length(texColorMask.xyz-colZone18)));
texen2[0][2] = (1.0-step(0.01,length(texColorMask.xyz-colZone19)));
texen2[0][3] = (1.0-step(0.01,length(texColorMask.xyz-colZone20)));
texen2[1][0] = (1.0-step(0.01,length(texColorMask.xyz-colZone21)));
texen2[1][1] = (1.0-step(0.01,length(texColorMask.xyz-colZone22)));
texen2[1][2] = (1.0-step(0.01,length(texColorMask.xyz-colZone23)));
texen2[1][3] = (1.0-step(0.01,length(texColorMask.xyz-colZone24)));
texen2[2][0] = (1.0-step(0.01,length(texColorMask.xyz-colZone25)));
texen2[2][1] = (1.0-step(0.01,length(texColorMask.xyz-colZone26)));
texen2[2][2] = (1.0-step(0.01,length(texColorMask.xyz-colZone27)));

float t1en = step(0.5, dommat4(texen1, TextureLightsEnables1) + dommat4(texen2, TextureLightsEnables2));
float t2en = step(0.5, dommat4(texen1, TextureDamage1Enables1) + dommat4(texen2, TextureDamage1Enables2));
float t3en = step(0.5, dommat4(texen1, TextureDamage2Enables1) + dommat4(texen2, TextureDamage2Enables2));
float t4en = step(0.5, dommat4(texen1, TextureUninstall1) + dommat4(texen2, TextureUninstall2));

float windowAlpha = clamp(texen1[1][2] + texen1[1][3] + texen1[2][0] + texen1[2][1] + texen1[2][2] + texen1[2][3], 0.0, 1.0);
float frontAlpha = clamp(texen1[0][0] + texen2[0][1] + texen2[0][2], 0.0, 1.0);
float tailAlpha = clamp(texen1[0][1] + texen2[0][3] + texen2[1][0] + texen2[1][1] + texen2[1][2], 0.0, 1.0);
float noTintAlpha = clamp(windowAlpha + frontAlpha + tailAlpha, 0.0, 1.0);

float ref_en = texen1[1][2] + texen1[1][3] + texen1[2][0] + texen1[2][1] + texen1[2][2] + texen1[2][3];
vec2 refTexCoord = SphereMap(normalize(normal), positionEye.xyz);
vec3 texRefA = texture2D(TextureReflectionA, refTexCoord).xyz;
vec3 texRefB = texture2D(TextureReflectionB, refTexCoord).xyz;
vec3 texRef = mix(texRefB, texRefA, ReflectionParam.x);
// (a painted door leaf has no glass left on its inside: a bus door's panes would mirror the sky, pale blue
// against the cream walls)
col = mix(col, texRef, ref_en*(0.1+ReflectionParam.y*0.5)*(1.0-meLensPainted));
col = mix(col, texRef/4.0, (1.0-ref_en)*(0.05 + ReflectionParam.z*0.3));

col = mix(col, texColorRust.xyz, texColorRust.a*TextureRustA);

vec3 paintColor = TexturePainColor.xyz;
vec4 texColorBlood2 = texture2D(TextureDamage2Overlay, texCoords1);
vec4 colmask = texture2D(TextureDamage1Overlay, texCoords1);
float intensity = dommat4(texen1, MatBlood1Enables1) + dommat4(texen2, MatBlood1Enables2);
float maskAlpha = step(0.5, dommat4(texen1, MatBlood2Enables1) + dommat4(texen2, MatBlood2Enables2));
col = addBlood(texColorBlood2, colmask, intensity, maskAlpha * windowAlpha, lighting, TintColourNew, col);

col = addDamage(col, texColorDamage1Shell, paintColor, lighting, TintColourNew, t2en*(1.0-noTintAlpha));
col = mix(col, texColorDamage1Shell.xyz, texColorDamage1Shell.a*t2en*noTintAlpha);
col = addDamage(col, texColorDamage2Shell, paintColor, lighting, TintColourNew, t3en*(1.0-noTintAlpha));
col = mix(col, texColorDamage2Shell.xyz, texColorDamage2Shell.a*t3en*noTintAlpha);

col = addBlood(texColorBlood2, colmask, intensity, maskAlpha * (1.0 - windowAlpha), lighting, TintColourNew, col);

col = mix(col, vec3(0.2), t4en);
col *= lighting * TintColourNew;
col = mix(col, texColorLights.xyz, texColorLights.a*t1en);
// (the exit marker is drawn on ME: LENS' floor only, by the part shader: here it
// would paint the body's own steps and sills by the door)

// A dark edge along the top of cut walls, like the game's cut-away building walls.
col *= mix(0.35, 1.0, smoothstep(0.2, 0.45, -meLensCut));
if (meLensRemoved)
	col = vec3(1.0, 0.0, 1.0);	// debugging: what the room clip removes
gl_FragColor = vec4(col, TexturePainColor.a);
